    h, w = len(grid), len(grid[0])
    # Green cross divides the canvas into sectors. It emits repeating
    # alternating horizontal/vertical strokes in each sector.
    hr = next((r for r,row in enumerate(grid) if all(v == 3 for v in row)), None)
    vc = next((c for c in range(w) if all(grid[r][c] == 3 for r in range(h))), None)
    if hr is None or vc is None:
        return [row[:] for row in grid]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if r == hr or c == vc:
                continue
            # In each quadrant, begin with vertical stripes at its outer edge,
            # interleaved with horizontal bars advancing away from the cross.
            if c < vc:
                stripe = (c % 2 == 1)
            else:
                stripe = ((c - vc - 1) % 2 == 1)
            if r < hr:
                bar = (r % 2 == 1)
            else:
                bar = ((r - hr - 1) % 2 == 1)
            if stripe or bar:
                out[r][c] = 4
    return out
''')"

